\set ON_ERROR_STOP on
set role anon;
do $$begin perform public.save_my_member_profile('Anonymous','','','visitor',null,false,false);raise exception 'Anonymous save allowed';exception when insufficient_privilege then raise notice 'PASS anonymous cannot submit';end$$;
reset role;
select set_config('request.jwt.claim.sub',md5('alice'),false);
set role authenticated;
select public.save_my_member_profile('Alice Synthetic','111','Synthetic address','visitor',md5('sanitary')::uuid,false,true);
select public.test_assert((select count(*)=1 from public.member_profile_intake),'member can read own profile');
select public.test_assert((select email='alice@example.invalid' and person_id is null and reviewed_at is null from public.member_profile_intake),'trusted account email and pending review');
do $$begin update public.member_profile_intake set reviewed_at=now();raise exception 'Direct update allowed';exception when insufficient_privilege then raise notice 'PASS no direct profile writes or approval forging';end$$;
do $$begin perform public.review_member_profile(md5('alice')::uuid,null);raise exception 'Member reviewed own submission';exception when insufficient_privilege then raise notice 'PASS member cannot approve directory updates';end$$;
select public.save_my_member_profile('Alice Synthetic','222','Updated synthetic address','member',md5('sanitary')::uuid,false,true);
select public.test_assert((select count(*)=1 from public.member_profile_intake),'repeat saves update same profile');
select public.test_assert((select count(*)=1 from public.member_contact_preferences_log),'unchanged preferences do not duplicate audit');
select public.save_my_member_profile('Alice Synthetic','222','','member',null,false,false);
select public.test_assert((select count(*)=2 from public.member_contact_preferences_log),'opt-out changes retain consent history');
do $$begin perform public.save_my_member_profile('Alice','','','pastor',null,true,true);raise exception 'Invalid self status allowed';exception when check_violation then raise notice 'PASS status cannot invent staff roles';end$$;
reset role;
select public.test_assert((select count(*)=0 from public.congregation_people),'self submission does not create duplicate directory record');
select set_config('request.jwt.claim.sub',md5('bob'),false);
set role authenticated;
select public.test_assert((select count(*)=0 from public.member_profile_intake),'other member cannot read profile contacts');
select public.test_assert((select count(*)=0 from public.member_contact_preferences_log),'other member cannot read consent history');
select public.save_my_member_profile('Bob Synthetic','','','exploring',null,false,false);
reset role;
insert into public.congregation_people(id,full_name,phone,social_contact,requests_school,created_by) values(md5('existing-person')::uuid,'Existing synthetic record','old','preserve me',true,md5('pastor')::uuid);
select set_config('request.jwt.claim.sub',md5('pastor'),false);
set role authenticated;
select public.test_assert((select count(*)=2 from public.member_profile_intake),'Pastor can review submitted profiles');
select public.review_member_profile(md5('alice')::uuid,md5('existing-person')::uuid);
select public.review_member_profile(md5('alice')::uuid,null);
reset role;
select public.test_assert((select count(*)=1 from public.congregation_people),'link and repeated review do not duplicate person');
select public.test_assert((select full_name='Alice Synthetic' and social_contact='preserve me' and requests_school from public.congregation_people where id=md5('existing-person')::uuid),'approved contact update retains unrelated directory history');
set role authenticated;
do $$begin perform public.review_member_profile(md5('bob')::uuid,md5('existing-person')::uuid);raise exception 'Duplicate account link allowed';exception when raise_exception then if sqlerrm<>'That directory record is already linked to another account' then raise;end if;raise notice 'PASS person cannot be claimed by two accounts';end$$;
select public.review_member_profile(md5('bob')::uuid,null);
reset role;
select public.test_assert((select count(*)=2 from public.congregation_people),'Pastor may explicitly create new person');
select set_config('request.jwt.claim.sub',md5('alice'),false);
set role authenticated;
select public.save_my_member_profile('Alice Synthetic','new phone','','member',null,false,false);
select public.test_assert((select reviewed_at is null and person_id=md5('existing-person')::uuid from public.member_profile_intake),'editing linked profile requires fresh review and preserves identity link');
reset role;
select public.test_assert((select phone='222' from public.congregation_people where id=md5('existing-person')::uuid),'unreviewed edit does not overwrite directory contacts');
select public.test_assert(not has_table_privilege('authenticated','public.member_contact_preferences_log','insert'),'members cannot forge consent audit entries');
select public.test_assert(not has_function_privilege('anon','public.review_member_profile(uuid,uuid)','execute'),'review function not public');
